/**
 * Compiles a filter expression string into `(event) => boolean`.
 *
 * Grammar (precedence: `()` > `NOT` > `AND` > `OR`):
 *   orExpr     := andExpr ( OR andExpr )*
 *   andExpr    := unary ( AND unary )*
 *   unary      := NOT unary | primary
 *   primary    := '(' orExpr ')' | comparison
 *   comparison := IDENT OP literal
 *               | IDENT [NOT] IN '(' literal ( ',' literal )* ')'
 *
 * @param {string} expr
 * @returns {(event: object) => boolean}
 */
export function compileFilter(expr) {
  const tokens = tokenizeDsl(expr);
  let pos = 0;

  function peek() {
    return tokens[pos] || null;
  }

  function consume(expectedType = null) {
    const tok = tokens[pos];
    if (!tok || (expectedType && tok.type !== expectedType)) {
      throw new LedgerError(
        ERROR_CODES.ERR_DSL_SYNTAX,
        `Expected ${expectedType || 'token'}, got ${tok ? tok.type : 'EOF'}`
      );
    }
    pos += 1;
    return tok;
  }

  function parseLiteral() {
    const tok = peek();
    if (!tok || !LITERAL_TYPES.has(tok.type)) {
      throw new LedgerError(
        ERROR_CODES.ERR_DSL_SYNTAX,
        `Expected literal, got ${tok ? tok.type : 'EOF'}`
      );
    }
    pos += 1;
    return tok.value;
  }

  function parseInList() {
    consume('IN');
    consume('(');
    const values = [parseLiteral()];
    while (peek() && peek().type === ',') {
      consume(',');
      values.push(parseLiteral());
    }
    consume(')');
    return values;
  }

  function parseComparison() {
    const field = consume('IDENT').value;
    const next = peek();
    if (next && (next.type === 'IN' || next.type === 'NOT')) {
      const negated = next.type === 'NOT';
      if (negated) consume('NOT');
      const values = parseInList();
      return negated
        ? (evt) => !values.includes(resolveField(evt, field))
        : (evt) => values.includes(resolveField(evt, field));
    }
    const op = consume('OP').value;
    const target = parseLiteral();
    return (evt) => {
      const actual = resolveField(evt, field);
      switch (op) {
        case '==': return actual === target;
        case '!=': return actual !== target;
        case '>': return actual > target;
        case '>=': return actual >= target;
        case '<': return actual < target;
        case '<=': return actual <= target;
        default: return false;
      }
    };
  }

  function parsePrimary() {
    const tok = peek();
    if (!tok) throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, 'Unexpected end of filter');
    if (tok.type === '(') {
      consume('(');
      const inner = parseOr();
      consume(')');
      return inner;
    }
    return parseComparison();
  }

  function parseUnary() {
    if (peek() && peek().type === 'NOT') {
      consume('NOT');
      const inner = parseUnary();
      return (evt) => !inner(evt);
    }
    return parsePrimary();
  }

  function parseAnd() {
    let left = parseUnary();
    while (peek() && peek().type === 'AND') {
      consume('AND');
      const right = parseUnary();
      const prev = left;
      left = (evt) => prev(evt) && right(evt);
    }
    return left;
  }

  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().type === 'OR') {
      consume('OR');
      const right = parseAnd();
      const prev = left;
      left = (evt) => prev(evt) || right(evt);
    }
    return left;
  }

  const fn = parseOr();
  if (pos !== tokens.length) {
    throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, `Unexpected trailing token ${tokens[pos].value}`);
  }
  return fn;
}
