        throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, 'Unterminated string literal');
      }
      tokens.push({ type: 'STRING', value: buf });
      i = j + 1;
      continue;
    }
    const two = expr.slice(i, i + 2);
    if (two === '==' || two === '!=' || two === '>=' || two === '<=') {
      tokens.push({ type: 'OP', value: two });
      i += 2;
      continue;
    }
    if (ch === '>' || ch === '<') {
      tokens.push({ type: 'OP', value: ch });
      i += 1;
      continue;
    }
    if (/[0-9-]/.test(ch)) {
      const m = /^-?\d+(?:\.\d+)?/.exec(expr.slice(i));
      if (m) {
        tokens.push({ type: 'NUMBER', value: Number(m[0]) });
        i += m[0].length;
        continue;
      }
    }
    const ident = /^[A-Za-z_][A-Za-z0-9_.]*/.exec(expr.slice(i));
    if (ident) {
      const word = ident[0];
      const upper = word.toUpperCase();
      if (upper === 'AND' || upper === 'OR' || upper === 'NOT') {
        tokens.push({ type: upper, value: upper });
      } else if (upper === 'TRUE' || upper === 'FALSE') {
        tokens.push({ type: 'BOOLEAN', value: upper === 'TRUE' });
      } else if (upper === 'NULL') {
        tokens.push({ type: 'NULL', value: null });
      } else {
        tokens.push({ type: 'IDENT', value: word });
      }
      i += word.length;
      continue;
    }
    throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, `Unexpected character: ${ch}`);
  }
  return tokens;
}

function resolveField(obj, pathStr) {
  const parts = String(pathStr).split('.');
  let cur = obj;
  for (const part of parts) {
    if (cur === null || cur === undefined || typeof cur !== 'object') return undefined;
    cur = cur[part];
  }
  return cur;
}

const LITERAL_TYPES = new Set(['STRING', 'NUMBER', 'BOOLEAN', 'NULL']);

/**
 * Compiles a filter expression string into `(event) => boolean`.
 *
 * Grammar (precedence: `()` > `NOT` > `AND` > `OR`):
 *   orExpr     := andExpr ( OR andExpr )*
 *   andExpr    := unary ( AND unary )*
 *   unary      := NOT unary | primary
 *   primary    := '(' orExpr ')' | comparison
 *   comparison := IDENT OP literal
 *               | IDENT [NOT] IN '(' literal ( ',' literal )* ')'
 *
 * @param {string} expr
 * @returns {(event: object) => boolean}
 */
export function compileFilter(expr) {
  const tokens = tokenizeDsl(expr);
  let pos = 0;

  function peek() {
    return tokens[pos] || null;
  }

  function consume(expectedType = null) {
    const tok = tokens[pos];
    if (!tok || (expectedType && tok.type !== expectedType)) {
      throw new LedgerError(
        ERROR_CODES.ERR_DSL_SYNTAX,
        `Expected ${expectedType || 'token'}, got ${tok ? tok.type : 'EOF'}`
      );
    }
    pos += 1;
    return tok;
  }

  function parseLiteral() {
    const tok = peek();
    if (!tok || !LITERAL_TYPES.has(tok.type)) {
      throw new LedgerError(
        ERROR_CODES.ERR_DSL_SYNTAX,
        `Expected literal, got ${tok ? tok.type : 'EOF'}`
      );
    }
    pos += 1;
    return tok.value;
  }

  function parseInList() {
    consume('IN');
    consume('(');
    const values = [parseLiteral()];
    while (peek() && peek().type === ',') {
      consume(',');
      values.push(parseLiteral());
    }
    consume(')');
    return values;
  }

  function parseComparison() {
    const field = consume('IDENT').value;
    const next = peek();
    if (next && (next.type === 'IN' || next.type === 'NOT')) {
      const negated = next.type === 'NOT';
      if (negated) consume('NOT');
      const values = parseInList();
      return negated
        ? (evt) => !values.includes(resolveField(evt, field))
        : (evt) => values.includes(resolveField(evt, field));
    }
    const op = consume('OP').value;
    const target = parseLiteral();
    return (evt) => {
      const actual = resolveField(evt, field);
      switch (op) {
        case '==': return actual === target;
        case '!=': return actual !== target;
        case '>': return actual > target;
        case '>=': return actual >= target;
        case '<': return actual < target;
        case '<=': return actual <= target;
        default: return false;
      }
    };
  }

  function parsePrimary() {
    const tok = peek();
    if (!tok) throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, 'Unexpected end of filter');
    if (tok.type === '(') {
      consume('(');
      const inner = parseOr();
      consume(')');
      return inner;
    }
    return parseComparison();
  }

  function parseUnary() {
    if (peek() && peek().type === 'NOT') {
      consume('NOT');
      const inner = parseUnary();
      return (evt) => !inner(evt);
    }
    return parsePrimary();
  }

  function parseAnd() {
    let left = parseUnary();
    while (peek() && peek().type === 'AND') {
      consume('AND');
      const right = parseUnary();
      const prev = left;
      left = (evt) => prev(evt) && right(evt);
    }
    return left;
  }

  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().type === 'OR') {
      consume('OR');
      const right = parseAnd();
      const prev = left;
      left = (evt) => prev(evt) || right(evt);
    }
    return left;
  }

  const fn = parseOr();
  if (pos !== tokens.length) {
    throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, `Unexpected trailing token ${tokens[pos].value}`);
  }
  return fn;
}

import { ERROR_CODES, LedgerError } from './errors.mjs';

/**
 * Computes graduated (marginal/tiered) usage charges.
 *
 * @param {number} units
 * @param {Array<{ upTo: number | null, unitRateCents: number }>} tiers
 * @returns {{ totalCents: number, breakdown: Array<{ tierIndex: number, upTo: number | null, units: number, unitRateCents: number, subtotalCents: number }> }}
 */
export function computeGraduatedCharge(units, tiers) {
  if (!Array.isArray(tiers) || tiers.length === 0) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, 'tiers must be a non-empty array');
  }
  if (!Number.isFinite(units) || units < 0) {
    return { totalCents: 0, breakdown: [] };
  }

  let prevUpTo = 0;
  let totalCents = 0;
  const breakdown = [];

  for (let i = 0; i < tiers.length; i += 1) {
    const tier = tiers[i];
    const cap = tier.upTo === null || tier.upTo === undefined || tier.upTo === Infinity ? Infinity : tier.upTo;
    if (units <= prevUpTo && i > 0) break;

    const bounded = Math.min(units, cap);
    const bandUnits = Math.max(0, bounded - prevUpTo + (prevUpTo > 0 ? 1 : 0));
    const subtotalCents = Math.floor(bandUnits * tier.unitRateCents);
    totalCents += subtotalCents;
    breakdown.push({
      tierIndex: i,
      upTo: cap === Infinity ? null : cap,
      units: bandUnits,
      unitRateCents: tier.unitRateCents,
      subtotalCents
    });
    if (cap === Infinity) break;
    prevUpTo = cap;
  }

  return { totalCents, breakdown };
}

/**
 * Computes volume (all-units-at-matched-tier-rate) usage charges.
 *
 * @param {number} units
 * @param {Array<{ upTo: number | null, unitRateCents: number }>} tiers
 * @returns {{ totalCents: number, matchedTierIndex: number, unitRateCents: number }}
 */
export function computeVolumeCharge(units, tiers) {
  if (!Array.isArray(tiers) || tiers.length === 0) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, 'tiers must be a non-empty array');
  }
  if (!Number.isFinite(units) || units < 0) {
    throw new LedgerError(ERROR_CODES.ERR_NEGATIVE_UNITS, 'units must be >= 0');
  }
  if (units === 0) {
    return { totalCents: 0, matchedTierIndex: 0, unitRateCents: tiers[0].unitRateCents };
  }

  for (let i = 0; i < tiers.length; i += 1) {
    const cap = tiers[i].upTo === null || tiers[i].upTo === undefined ? Infinity : tiers[i].upTo;
    if (units <= cap) {
      return {
        totalCents: Math.round(units * tiers[i].unitRateCents),
        matchedTierIndex: i,
        unitRateCents: tiers[i].unitRateCents
      };
    }
  }
  const lastIdx = tiers.length - 1;
  return {
    totalCents: Math.round(units * tiers[lastIdx].unitRateCents),
    matchedTierIndex: lastIdx,
    unitRateCents: tiers[lastIdx].unitRateCents
  };
}

