import { INVOICE_STATUS } from './constants.mjs';
import { computeGraduatedCharge } from './tierEngine.mjs';
import { applyCredits } from './creditPool.mjs';
import { encodeFrozenWireDigest } from './frozenWire.mjs';
import { compileFilter } from './queryDsl.mjs';
import { ERROR_CODES, LedgerError } from './errors.mjs';

const UNTAGGED = 'untagged';

function compareCodeUnits(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

function compareGroupValues(a, b) {
  const aUntagged = a === UNTAGGED;
  const bUntagged = b === UNTAGGED;
  if (aUntagged && bUntagged) return 0;
  if (aUntagged) return 1;
  if (bUntagged) return -1;
  return compareCodeUnits(String(a), String(b));
}

/**
 * Filters, groups, and prices raw usage events.
 *
 * @returns {{ lineItems: object[], usageSubtotalCents: number, excludedEventCount: number }}
 */
function buildEventLineItems(events, metricTiers, filterExpr, groupByTag) {
  const predicate = filterExpr === null || filterExpr === undefined ? null : compileFilter(filterExpr);
  const grouped = groupByTag !== null && groupByTag !== undefined;

  /** @type {Map<string, Map<any, number>>} */
  const pools = new Map();
  let excludedEventCount = 0;

  for (const evt of events) {
    if (predicate && !predicate(evt)) {
      excludedEventCount += 1;
      continue;
    }
    const units = evt?.units;
    if (typeof units !== 'number' || !Number.isFinite(units)) {
      throw new LedgerError(ERROR_CODES.ERR_INVALID_EVENT, 'event units must be a finite number', { event: evt });
    }
    if (units < 0) {
      throw new LedgerError(ERROR_CODES.ERR_NEGATIVE_UNITS, 'event units must be >= 0', { event: evt });
    }
    const metric = evt.metric;
    const groupValue = grouped ? (evt.tags?.[groupByTag] ?? UNTAGGED) : null;
    let byGroup = pools.get(metric);
    if (!byGroup) {
      byGroup = new Map();
      pools.set(metric, byGroup);
    }
    byGroup.set(groupValue, (byGroup.get(groupValue) || 0) + units);
  }

  const lineItems = [];
  let usageSubtotalCents = 0;
  for (const [metric, byGroup] of pools) {
    for (const [groupValue, totalUnits] of byGroup) {
      const { totalCents } = computeGraduatedCharge(totalUnits, metricTiers?.[metric]);
      usageSubtotalCents += totalCents;
      const item = { metric, units: totalUnits, amountCents: totalCents };
      if (grouped) item.groupValue = groupValue;
      lineItems.push(item);
    }
  }

  lineItems.sort((a, b) => {
    const byMetric = compareCodeUnits(String(a.metric), String(b.metric));
    if (byMetric !== 0 || !grouped) return byMetric;
    return compareGroupValues(a.groupValue, b.groupValue);
  });

  return { lineItems, usageSubtotalCents, excludedEventCount };
}

/**
 * Builds an invoice from usage rows (or raw events) and credit grants.
 *
 * When `events` is an array it supersedes `usageRows`: events are filtered by
 * `filterExpr`, pooled by `(metric, groupValue)` and priced with graduated
 * `metricTiers[metric]`.
 *
 * @param {object} params
 * @returns {object}
 */
export function buildInvoice({
  invoiceId,
  accountId,
  currency = 'USD',
  usageRows = [],
  events = undefined,
  metricTiers = {},
  filterExpr = null,
  groupByTag = null,
  grants = [],
  asOfMs = 0
} = {}) {
  let lineItems = [];
  let usageSubtotalCents = 0;
  let excludedEventCount = 0;

  if (Array.isArray(events)) {
    ({ lineItems, usageSubtotalCents, excludedEventCount } = buildEventLineItems(
      events,
      metricTiers,
      filterExpr,
      groupByTag
    ));
  } else {
    for (const row of usageRows) {
      const { totalCents } = computeGraduatedCharge(row.units, row.tiers);
      usageSubtotalCents += totalCents;
      lineItems.push({
        metric: row.metric,
        units: row.units,
        amountCents: totalCents
      });
    }
  }

  const creditResult = applyCredits(usageSubtotalCents, grants, asOfMs);
  const totalDueCents = creditResult.remainingChargeCents;
  const status = INVOICE_STATUS.FINALIZED;
  const wireDigest = encodeFrozenWireDigest({
    invoiceId,
    accountId,
    currency,
    totalDueCents,
    status
  });

  return {
    invoiceId,
    accountId,
    currency,
    status,
    lineItems,
    usageSubtotalCents,
    excludedEventCount,
    appliedCreditsCents: creditResult.appliedCents,
    creditAllocations: creditResult.allocations,
    totalDueCents,
    wireDigest
  };
}

