    accountId,
    currency,
    status,
    lineItems,
    usageSubtotalCents,
    excludedEventCount,
    appliedCreditsCents: creditResult.appliedCents,
    creditAllocations: creditResult.allocations,
    totalDueCents,
    wireDigest
  };
}

